#!/usr/bin/env bash
# ncpgen's tests, with no vendor file at all: npunet.py's and frame.py's self-tests, then every network of
# tests/golden.txt (our own seeded networks: the corpus and a final unseen set of larger chains) generated by ncpgen with
# NPUC's own activation table (--grelu npuc) and compared by sha256 with the NCP Samsung's NPUC compiled for it.
#   tests/run.sh [-j N]          exit 0 when everything passes
set -uo pipefail
R=$(cd "$(dirname "$0")/.." && pwd)
J=4; [ "${1:-}" = -j ] && J=$2
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
fail=0
python3 -I "$R/ncpgen/npunet.py" selftest | tail -n 1 | grep -q PASS && echo "npunet selftest: PASS" || { echo "npunet selftest: FAIL"; fail=1; }
python3 -I "$R/ncpgen/frame.py" selftest | tail -n 1 | grep -q PASS && echo "frame selftest: PASS" || { echo "frame selftest: FAIL"; fail=1; }
one() {
  IFS='|' read -r name spec opts sha <<< "$1"
  python3 -I "$R/oracle/npuc-variant.py" "$T/$name.json" $spec > /dev/null 2>&1 \
    && python3 -I "$R/ncpgen/ncpgen.py" gen "$T/$name.json" "$T/$name.ncp" $opts --grelu npuc > /dev/null 2>&1 \
    && [ "$(sha256sum < "$T/$name.ncp" | cut -d' ' -f1)" = "$sha" ] && echo "ok $name" || echo "FAIL $name"
}
export -f one; export R T
res=$(grep -v '^#' "$R/tests/golden.txt" | tr '\n' '\0' | xargs -0 -n 1 -P "$J" bash -c 'one "$1"' _)
n=$(echo "$res" | grep -c '^ok '); m=$(echo "$res" | grep -c '^FAIL ')
echo "$res" | grep '^FAIL ' || true
echo "golden: $n of $((n + m)) NCPs byte for byte = NPUC's"
[ "$m" = 0 ] || fail=1
[ $fail = 0 ] && echo "tests: PASS" || echo "tests: FAIL"
exit $fail
